package com.abhishek.ecommerce.payment;import com.abhishek.ecommerce.common.*;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.stereotype.Component;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;@Component public class PaymentConsumer{final PaymentRepository repo;final KafkaTemplate<String,DomainEvent>kafka;PaymentConsumer(PaymentRepository r,KafkaTemplate<String,DomainEvent>k){repo=r;kafka=k;}@KafkaListener(topics="order-events",groupId="payment-service")void onOrder(DomainEvent e){if(e.eventType()!=EventType.ORDER_CREATED)return;Payment p=new Payment();p.setOrderId(e.aggregateId());p.setUserId(e.userId());p.setAmount(new BigDecimal(e.payload()));p.setStatus("SUCCESS");repo.save(p);kafka.send("payment-events",new DomainEvent(EventType.PAYMENT_SUCCESS,UUID.randomUUID().toString(),e.aggregateId(),e.userId(),"{}",Instant.now()));}}